pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 prevBalance, uint256 msgValue) public {
        // Bound prevBalance to avoid overflow on the sum itself when checking,
        // but keep domain wide enough that the bug can trigger.
        prevBalance = bound(prevBalance, 0, type(uint256).max - 1);
        // msgValue can be anything up to max, allowing overflow in the mutant.
        msgValue = bound(msgValue, 0, type(uint256).max);

        // Deploy fresh contract to have clean state.
        c = new C(address(this));

        // Use a fixed sender address for fuzzing.
        address sender = address(0x100);
        vm.deal(sender, type(uint256).max);

        // Set up previous balance by using Put. Since we cannot directly write storage,
        // send prevBalance to the fallback. The fallback calls Put(0) with msg.value.
        // This requires that the fallback does not overflow itself, so prevBalance must be
        // set in a way that obeys the checked version or we use the mutant's behavior.
        // To avoid tripping the overflow during setup on the reference, we send prevBalance
        // in a single call. The reference will require no overflow, but the mutant will allow it.
        // We must ensure that the setup succeeds even on the reference.
        // We assume prevBalance is set via a single call that won't overflow a zero balance.
        if (prevBalance > 0) {
            vm.prank(sender);
            (bool ok,) = address(c).call{value: prevBalance}("");
            // If the setup fails (e.g., overflow in reference), skip this fuzz run.
            if (!ok) {
                return;
            }
        }

        // Record the balance after setup.
        uint256 balanceBefore = c.Acc(sender).balance;

        // Now perform the fuzzed Put via the fallback with msgValue.
        vm.prank(sender);
        (bool success,) = address(c).call{value: msgValue}("");
        // If the call itself reverts (e.g., reference overflow check), we handle it.
        // The invariant we check is: if the call succeeded, then the new balance
        // must equal balanceBefore + msgValue without overflow.
        // The reference always reverts on overflow, the mutant may succeed with wrap.

        if (success) {
            // Call succeeded, so check the balance.
            uint256 balanceAfter = c.Acc(sender).balance;
            // Reference: balanceAfter == balanceBefore + msgValue (no overflow).
            // Mutant: may have balanceAfter < balanceBefore (overflow).
            assertTrue(balanceAfter >= balanceBefore);
        }
    }
}

