        vm.warp(block.timestamp + unlockDelta + 1);

        // Record balance before collect attempt
        uint256 balanceBefore = c.Acc(user).balance;

        // Attempt to collect
        vm.prank(user);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.Acc(user).balance;

        // Property: if the attempted amount could have been collected (balance >= MinSum, balance >= collectAmount, time > unlockTime),
        // then the balance after collection MUST equal balanceBefore - collectAmount.
        // The bug allows exactly these conditions but prevents the deduction when balance == MinSum due to strict > check.
        if (initialDeposit >= 1 ether && initialDeposit >= collectAmount) {
            assertTrue(balanceAfter == uint256(balanceBefore) - uint256(collectAmount));
        } else {
            assertTrue(true); // irrelevant branch
        }
    }
}

